mapper.select:
SELECT audit_tenant_id, operation_id, request_identity_hash, operation_kind,
       targets_json::text AS targets_json,
       response_metadata_json::text AS response_metadata_json
  FROM batch.config_batch_operation
 WHERE audit_tenant_id = #{auditTenantId}
   AND request_identity_hash = #{requestIdentityHash}

SELECT result_json::text
  FROM batch.config_batch_target_receipt
 WHERE audit_tenant_id = #{auditTenantId}
   AND operation_id = #{operationId}
   AND target_ordinal = #{targetOrdinal}
   AND tenant_id = #{tenantId}
